using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;
public static class FinanceCommunication {
 public static readonly string[] Variables=["invoice_number","invoice_total","outstanding_amount","due_date","receipt_number","payment_amount","finance_link"];
 public static readonly string[] Templates=["Member dues issued","Chapter dues issued","Payment reminder","Overdue notice","Payment received","Receipt available","Refund processed","Expense approval request"];
 public static void Seed(AppDb db,Guid tenant){foreach(var name in Templates)db.Add(new CommunicationTemplate{TenantId=tenant,Name=name,Category="Finance",Channel="InApp",Subject=name,Body="Hello {{member_name}}, "+name+". Invoice {{invoice_number}}, outstanding {{outstanding_amount}}, due {{due_date}}. {{finance_link}}"});}
 public static async Task Queue(FinanceInvoice invoice,Guid author,string channel,Guid? accountId,Guid? templateId,string key,AppDb db,IConfiguration config){var (a,finance,comm)=FinanceWorker.Context(db,author,config);await finance.Require(invoice.TenantId,invoice.EntityId,invoice.UnitId,"finance.collect");await a.Require(invoice.TenantId,"communications.send",invoice.UnitId);if(invoice.Status!="Issued"||invoice.Kind!="Invoice")throw new DomainException("Only issued invoices can be communicated");var members=db.Memberships.Where(m=>m.TenantId==invoice.TenantId&&(invoice.MembershipId!=null?m.Id==invoice.MembershipId:invoice.BilledUnitId!=null&&m.ChapterId==invoice.BilledUnitId&&db.OfficerAppointments.Any(ap=>ap.TenantId==invoice.TenantId&&ap.MembershipId==m.Id&&ap.Status=="Approved"&&ap.StartsAt<=DateTimeOffset.UtcNow&&ap.EndsAt>DateTimeOffset.UtcNow&&db.OfficerPositions.Any(pos=>pos.Id==ap.PositionId&&pos.Name.Contains("Treasurer")))));var permitted=a.Visible(invoice.TenantId,"communications.send").Select(u=>u.Id);members=members.Where(m=>permitted.Contains(m.ChapterId));var recipients=await comm.Resolve(invoice.TenantId,members,channel);var template=templateId==null?null:await db.Set<CommunicationTemplate>().SingleOrDefaultAsync(t=>t.TenantId==invoice.TenantId&&t.Id==templateId&&t.Active&&t.Channel==channel&&(t.UnitId==null||t.UnitId==invoice.UnitId));if(templateId!=null&&template==null)throw new DomainException("Use an active finance template in the same channel and scope");foreach(var r in recipients.Where(r=>r.Reason=="Eligible")){var dedup=key+":"+r.PersonId;if(await db.Outbox.AnyAsync(o=>o.TenantId==invoice.TenantId&&o.IdempotencyKey==dedup))continue;var vars=r.Variables;vars["invoice_number"]=invoice.Number;vars["invoice_total"]=invoice.Currency+" "+invoice.Total.ToString(System.Globalization.CultureInfo.InvariantCulture);vars["outstanding_amount"]=invoice.Currency+" "+(invoice.Total-invoice.Paid-invoice.Credited).ToString(System.Globalization.CultureInfo.InvariantCulture);vars["due_date"]=invoice.DueOn.ToString("yyyy-MM-dd");vars["receipt_number"]="";vars["payment_amount"]="";vars["finance_link"]=(config["PublicUrl"]??"").TrimEnd('/')+"/app/finance/my";var token=CommunityService.Token();var body=CommunicationService.Render(template?.Body??"Hello {{member_name}}, invoice {{invoice_number}} has {{outstanding_amount}} outstanding, due {{due_date}}. {{finance_link}}",vars);if(channel=="Email")body+="\nUnsubscribe: "+(config["PublicUrl"]??"").TrimEnd('/')+"/unsubscribe?token="+token;var job=new Outbox{FinanceInvoiceId=invoice.Id,SenderId=author,TenantId=invoice.TenantId,UnitId=invoice.UnitId,UserId=r.UserId,MembershipId=r.MembershipId,AccountId=accountId,Channel=channel,Recipient=r.Destination,Subject=CommunicationService.Render(template?.Subject??"Invoice {{invoice_number}}",vars),Body=body,IdempotencyKey=dedup,UnsubscribeHash=CommunityService.Hash(token)};if(channel=="WhatsApp"){if(template?.ProviderStatus!="APPROVED"||template.ProviderAccountId!=accountId)throw new DomainException("WhatsApp reminders require an approved, account-bound template");job.TemplateName=template.ProviderName;job.TemplateLanguage=template.Language;job.TemplateParameters=JsonSerializer.Serialize(MetaTemplates.Parameters(template,vars));}db.Add(job);}}
 public static async Task NotifyMember(FinanceRecord source,Guid? membership,string title,string body,string key,AppDb db){if(membership==null)return;var member=await db.Memberships.AsNoTracking().SingleOrDefaultAsync(m=>m.TenantId==source.TenantId&&m.Id==membership&&m.Status=="Active");if(member==null||!CommunityService.CommunicationAllowed(member.Privacy))return;var user=await db.Persons.Where(p=>p.Id==member.PersonId).Select(p=>p.UserId).SingleAsync();if(user==null||await db.Set<CommunicationPreference>().AnyAsync(p=>p.TenantId==source.TenantId&&p.UserId==user&&!p.InApp))return;if(await db.Outbox.AnyAsync(o=>o.TenantId==source.TenantId&&o.IdempotencyKey==key))return;db.Add(new Outbox{FinanceInvoiceId=source is FinanceInvoice?source.Id:null,TenantId=source.TenantId,UnitId=source.UnitId,UserId=user,MembershipId=member.Id,Recipient=user.ToString()!,Channel="InApp",Subject=title,Body=body,IdempotencyKey=key});}
 public static async Task NotifyChapter(FinanceInvoice invoice,AppDb db){if(invoice.BilledUnitId==null)return;var ids=await db.OfficerAppointments.Where(ap=>ap.TenantId==invoice.TenantId&&ap.Status=="Approved"&&ap.StartsAt<=DateTimeOffset.UtcNow&&ap.EndsAt>DateTimeOffset.UtcNow&&db.Memberships.Any(m=>m.Id==ap.MembershipId&&m.ChapterId==invoice.BilledUnitId)&&db.OfficerPositions.Any(p=>p.Id==ap.PositionId&&p.Name.Contains("Treasurer"))).Select(ap=>ap.MembershipId).Distinct().Take(100).ToListAsync();foreach(var id in ids)await NotifyMember(invoice,id,"Chapter obligation "+invoice.Number,invoice.Currency+" "+invoice.Total+" due "+invoice.DueOn,"finance-chapter:"+invoice.Id+":"+id,db);}
 public static async Task Approval(FinanceRecord source,Guid author,string title,AppDb db){var users=await db.Assignments.Where(x=>x.TenantId==source.TenantId&&x.UserId!=author&&x.RevokedAt==null&&db.GovernanceRoles.Any(r=>r.Id==x.RoleId&&r.Permissions.Contains("finance.approve"))).Select(x=>x.UserId).Distinct().Take(500).ToListAsync();foreach(var user in users){if(!await MailWorker.Authority(db,source.TenantId,user,source.UnitId,"finance.approve")||await db.Set<CommunicationPreference>().AnyAsync(p=>p.TenantId==source.TenantId&&p.UserId==user&&!p.InApp))continue;var key="finance-review:"+source.Id+":"+user;if(await db.Outbox.AnyAsync(o=>o.TenantId==source.TenantId&&o.IdempotencyKey==key))continue;db.Add(new Outbox{TenantId=source.TenantId,UnitId=source.UnitId,UserId=user,Recipient=user.ToString(),Channel="InApp",Subject=title,Body="An authorized independent financial review is requested. Open the finance workspace for current permitted details.",IdempotencyKey=key});}}
 public static async Task Dispatch(AppDb db,IConfiguration config,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var rules=await db.Set<FinanceReminder>().Where(r=>r.Enabled).OrderBy(r=>r.Id).Take(100).ToListAsync(ct);foreach(var rule in rules){if(!await MailWorker.Authority(db,rule.TenantId,rule.AuthorId,rule.UnitId,"finance.collect")||!await MailWorker.Authority(db,rule.TenantId,rule.AuthorId,rule.UnitId,"communications.send"))continue;var date=FinanceService.Today.AddDays(-rule.DaysFromDue);var invoices=await db.Set<FinanceInvoice>().Where(i=>i.TenantId==rule.TenantId&&i.EntityId==rule.EntityId&&i.UnitId==rule.UnitId&&i.Status=="Issued"&&i.Kind=="Invoice"&&i.Total>i.Paid+i.Credited&&i.DueOn==date&&!db.Set<FinanceReminderRun>().Any(r=>r.RuleId==rule.Id&&r.InvoiceId==i.Id&&r.Cycle==date.ToString("yyyy-MM-dd"))).OrderBy(i=>i.Id).Take(100).ToListAsync(ct);foreach(var i in invoices){await FinanceService.Lock(db,rule.TenantId);try{await Queue(i,rule.AuthorId,rule.Channel,rule.AccountId,rule.TemplateId,"finance-reminder:"+rule.Id+":"+i.Id+":"+date,db,config);db.Add(new FinanceReminderRun{TenantId=rule.TenantId,EntityId=rule.EntityId,UnitId=rule.UnitId,RuleId=rule.Id,InvoiceId=i.Id,Cycle=date.ToString("yyyy-MM-dd"),Status="Evaluated"});}catch(DomainException){db.Add(new FinanceReminderRun{TenantId=rule.TenantId,EntityId=rule.EntityId,UnitId=rule.UnitId,RuleId=rule.Id,InvoiceId=i.Id,Cycle=date.ToString("yyyy-MM-dd"),Status="Configuration required"});}}}await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}
}
public static partial class FinanceEndpoints {
 static void MapReminders(RouteGroupBuilder t){
 t.MapGet("/reminders",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<FinanceReminder>(tenant,entity:entity).OrderBy(r=>r.Name).Take(100).ToListAsync());
 t.MapPost("/reminders",async(Guid tenant,FinanceReminder r,AppDb db,Access a,FinanceService s)=>{await s.Require(tenant,r.EntityId,r.UnitId,"finance.collect");await a.Require(tenant,"communications.send",r.UnitId);if(r.Name.Length is <3 or >160||r.DaysFromDue is < -365 or >365||!CommunicationService.Channels.Contains(r.Channel))throw new DomainException("Check reminder name, channel and day offset");var reminder=new FinanceReminder{TenantId=tenant,EntityId=r.EntityId,UnitId=r.UnitId,Name=r.Name,DaysFromDue=r.DaysFromDue,Channel=r.Channel,AccountId=r.AccountId,TemplateId=r.TemplateId,AuthorId=a.UserId,Enabled=r.Enabled};db.Add(reminder);a.Audit(tenant,"finance.reminder.created",reminder.Id);await db.SaveChangesAsync();return Results.Ok(reminder);});
 t.MapPost("/reminders/{id:guid}/toggle",async(Guid tenant,Guid id,AppDb db,Access a,FinanceService s)=>{var r=await db.Set<FinanceReminder>().SingleOrDefaultAsync(r=>r.TenantId==tenant&&r.Id==id)??throw new AccessDeniedException();await s.Require(tenant,r.EntityId,r.UnitId,"finance.collect");r.Enabled=!r.Enabled;a.Audit(tenant,"finance.reminder.toggled",id);await db.SaveChangesAsync();return Results.Ok(r);});
 t.MapGet("/reminders/{id:guid}/runs",async(Guid tenant,Guid id,AppDb db,FinanceService s)=>{var r=await db.Set<FinanceReminder>().SingleOrDefaultAsync(r=>r.TenantId==tenant&&r.Id==id)??throw new AccessDeniedException();await s.Require(tenant,r.EntityId,r.UnitId);return await db.Set<FinanceReminderRun>().Where(x=>x.TenantId==tenant&&x.RuleId==id).OrderByDescending(x=>x.At).Take(100).ToListAsync();});
 t.MapPost("/invoices/{id:guid}/send",async(Guid tenant,Guid id,SendInvoice r,AppDb db,Access a,FinanceService s,IConfiguration config)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var i=await s.Invoice(tenant,id,false);await s.Require(tenant,i.EntityId,i.UnitId,"finance.collect");if(!CommunicationService.Channels.Contains(r.Channel))throw new DomainException("Unsupported channel");await FinanceCommunication.Queue(i,a.UserId,r.Channel,r.AccountId,r.TemplateId,"finance-send:"+id+":"+r.Key,db,config);a.Audit(tenant,"finance.invoice.communicated",id,new{r.Channel});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{status="Eligibility evaluated; inspect delivery tracking for transport status"});});
 }
}
public record SendInvoice(string Channel="InApp",Guid? AccountId=null,Guid? TemplateId=null,string Key="initial");
